local ChairMaker = {}
local PRODUCTS = {
    simple_oak_chair = { name = "Preprost hrastov stol", woodCost = 3, time = 4, cost = 60, beauty = 18, happiness = 1, description = "Preprost hrastov stol za hišo." },
    carved_walnut_chair = { name = "Izrezljan orehov stol", woodCost = 3, leatherCost = 1, time = 6, cost = 160, beauty = 32, happiness = 2, prestige = 2, description = "Izrezljan orehov stol za trgovce." },
    silver_trimmed_chair = { name = "Srebrnoobrobljeni stol", woodCost = 3, silverCost = 1, leatherCost = 1, time = 9, cost = 380, beauty = 48, happiness = 2, prestige = 6, description = "Srebrnoobrobljeni stol za plemiče." },
    gold_inlaid_chair = { name = "Zlatovloženi stol", woodCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, time = 13, cost = 900, beauty = 62, happiness = 3, prestige = 14, description = "Zlatovloženi stol za visoke plemiče." },
    jewel_set_throne_chair = { name = "Draguljasta prestolni stol", woodCost = 4, goldCost = 2, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 17, cost = 2000, beauty = 78, happiness = 5, prestige = 27, description = "Prestolni stol z draguljem za visoko plemstvo." },
    royal_grand_chair = { name = "Kraljevski veliki stol", woodCost = 6, goldCost = 3, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4500, beauty = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski stol z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    chair_workshop = { name = "Stolni delavnica", cost = { gold = 240, wood = 160, stone = 100 }, upkeep = 5, qualityBonus = 5 },
    furniture_loft = { name = "Pohištvena podstrešje", cost = { gold = 880, wood = 320, stone = 220, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    master_cabinet_atelier = { name = "Mojstrski mizarski atelje", cost = { gold = 2500, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_furniture_palace = { name = "Kraljevska pohištvena palača", cost = { gold = 10500, wood = 600, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
ChairMaker.woodStock = 20; ChairMaker.leatherStock = 10; ChairMaker.silverStock = 6; ChairMaker.goldStock = 6; ChairMaker.jewelStock = 4; ChairMaker.pearlStock = 4
ChairMaker.productStock = {}; ChairMaker.buildings = {}; ChairMaker.maker = nil; ChairMaker.activeMaking = {}; ChairMaker.totalProducts = 0; ChairMaker.dayTimer = 0
function ChairMaker.init() ChairMaker.woodStock=20; ChairMaker.leatherStock=10; ChairMaker.silverStock=6; ChairMaker.goldStock=6; ChairMaker.jewelStock=4; ChairMaker.pearlStock=4; ChairMaker.productStock={}; ChairMaker.buildings={}; ChairMaker.maker=nil; ChairMaker.activeMaking={}; ChairMaker.totalProducts=0; ChairMaker.dayTimer=0; print("[ChairMaker] Royal Chair Maker System initialized (6 products, 4 buildings)") end
function ChairMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChairMaker.maker={name=n or ("Stolar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stolar najet: %s (spretnost: %d)",ChairMaker.maker.name,s),"success") end; return true end
function ChairMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChairMaker.build(id) local ok,e=ChairMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChairMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChairMaker.getQualityBonus() local b=0; for _,bd in ipairs(ChairMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChairMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ChairMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ChairMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ChairMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChairMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChairMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChairMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChairMaker.buildings==0 then return false,"Potrebna stolni delavnica" end; if not ChairMaker.maker then return false,"Potreben stolar" end; return true end
function ChairMaker.make(pt,qty) qty=qty or 1; local ok,e=ChairMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ChairMaker.woodStock=ChairMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ChairMaker.leatherStock=ChairMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ChairMaker.silverStock=ChairMaker.silverStock-d.silverCost*qty end; if d.goldCost then ChairMaker.goldStock=ChairMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ChairMaker.jewelStock=ChairMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChairMaker.pearlStock=ChairMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ChairMaker.maker then t=math.max(1,t-math.floor(ChairMaker.maker.skill/13)) end; table.insert(ChairMaker.activeMaking,{id="chair_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChairMaker.completeMaking(m) local q=1.0+(ChairMaker.getQualityBonus()/100); if ChairMaker.maker then q=q+(ChairMaker.maker.skill/140) end; q=math.min(2.5,q); ChairMaker.productStock[m.productType]=(ChairMaker.productStock[m.productType] or 0)+m.quantity; ChairMaker.totalProducts=ChairMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChairMaker.maker then ChairMaker.maker.itemsMade=ChairMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ChairMaker.maker.skill=math.min(100,ChairMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stol izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chair.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function ChairMaker.update(dt) if not _G.state then return end; ChairMaker.dayTimer=ChairMaker.dayTimer+dt; if ChairMaker.dayTimer>=30 then ChairMaker.dayTimer=0; for i=#ChairMaker.activeMaking,1,-1 do local m=ChairMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChairMaker.completeMaking(m); table.remove(ChairMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChairMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChairMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChairMaker.getStats() return {woodStock=ChairMaker.woodStock,leatherStock=ChairMaker.leatherStock,silverStock=ChairMaker.silverStock,goldStock=ChairMaker.goldStock,jewelStock=ChairMaker.jewelStock,pearlStock=ChairMaker.pearlStock,productStock=ChairMaker.productStock,numBuildings=#ChairMaker.buildings,hasMaker=ChairMaker.maker~=nil,makerName=ChairMaker.maker and ChairMaker.maker.name or "—",makerSkill=ChairMaker.maker and ChairMaker.maker.skill or 0,activeMaking=#ChairMaker.activeMaking,totalProducts=ChairMaker.totalProducts} end
return ChairMaker
